stylesheets.stylesheet:
.myreactions-container {
  padding: 10px;
  border-top: 1px solid #ccc;
}
.myreactions-container.myreactions-profile-container {
	padding: 0;
	border: 0;
}
.myreactions-reactions, .myreactions-reaction {
  background: #f5f5f5;
  border: 1px solid #ccc;
  display: inline-block;
  border-radius: 6px;
}

.myreactions-reaction {
  display: inline-block;
  margin: 2px;
  padding: 5px;
  float: left;
}
.myreactions-reactions {
	float: left;
	margin-right: 5px;
}
.myreactions-reaction span {
  float: right;
  margin-left: 5px;
}
.myreactions-reactions img {
  margin: 5px;
  float: left;
  display: inline-block;
}

/* Add Reaction */
.reaction-add {
  display: none;
  margin: 0;
  float: left;
  cursor: pointer;
}
.reaction-add span {
  display: none;	
}
.myreactions-reaction + .reaction-add {
  margin: 2px;	
}
.myreactions-container:hover .reaction-add, .reaction-add.reaction-add-force, .reaction-add.reaction-add-force span {
  display: inline-block;
}

/* Reacted */
.myreactions-container .myreactions-reacted img {
  position: relative;
}
.myreactions-container .myreactions-reacted img + span {
	cursor: pointer;
	display: inline-block;
    margin-right: 5px;
}

/* Reaction Modal */
.myreactions-react img {
	width: 24px;
	height: 24px;
	padding: 5px;
}
.reaction-add, .myreactions-react img {
	cursor: pointer;
}
.myreactions-react img.disabled {
	cursor: not-allowed;
	opacity: 0.25;
	-webkit-filter: grayscale(100%);
    filter: grayscale(100%);
}

/* Reaction image sizes */
.myreactions-container.reactions-16 img {
  width: 16px;
  height: 16px;
}
.myreactions-container.reactions-16 .myreactions-reaction span, .myreactions-container.reactions-16 .myreactions-reacted {
  font-size: 12px;
  line-height: 16px;
}
.myreactions-container.reactions-16 .myreactions-reactions .reaction-add + span {
  font-size: 12px;
  line-height: 26px;
}
.myreactions-container.reactions-16 .myreactions-reacted img {
  top: 4px;
}
.myreactions-container.reactions-20 img {
  width: 20px;
  height: 20px;
}
.myreactions-container.reactions-20 .myreactions-reaction span, .myreactions-container.reactions-20 .myreactions-reacted {
  font-size: 13px;
  line-height: 20px;
}
.myreactions-container.reactions-20 .myreactions-reactions .reaction-add + span {
  font-size: 13px;
  line-height: 30px;
}
.myreactions-container.reactions-20 .myreactions-reacted img {
  top: 6px;
}
.myreactions-container.reactions-24 img {
  width: 24px;
  height: 24px;
}
.myreactions-container.reactions-24 .myreactions-reaction span, .myreactions-container.reactions-24 .myreactions-reacted {
  font-size: 14px;
  line-height: 24px;
}
.myreactions-container.reactions-24 .myreactions-reactions .reaction-add + span {
  font-size: 14px;
  line-height: 34px;
}
.myreactions-container.reactions-24 .myreactions-reacted img {
  top: 7px;
}
.myreactions-container.reactions-28 img {
  width: 28px;
  height: 28px;
}
.myreactions-container.reactions-28 .myreactions-reaction span, .myreactions-container.reactions-28 .myreactions-reacted {
  font-size: 15px;
  line-height: 28px;
}
.myreactions-container.reactions-28 .myreactions-reactions .reaction-add + span {
  font-size: 15px;
  line-height: 38px;
}
.myreactions-container.reactions-28 .myreactions-reacted img {
  top: 7px;
}
.myreactions-container.reactions-32 img {
  width: 32px;
  height: 32px;
}
.myreactions-container.reactions-32 .myreactions-reaction span, .myreactions-container.reactions-32 .myreactions-reacted {
  font-size: 16px;
  line-height: 32px;
}
.myreactions-container.reactions-32 .myreactions-reactions .reaction-add + span {
  font-size: 16px;
  line-height: 42px;
}
.myreactions-container.reactions-32 .myreactions-reacted img {
  top: 8px;
}

.toggle, [id^="drop"] {
    display: none;
}
nav {
    background: #333;
    margin: 0;
    padding: 0;
}
nav::after {
    clear: both;
    content: "";
    display: table;
}
nav ul {
    list-style: outside none none;
    margin: 0;
    padding: 0;
    position: relative;
}
nav ul li {
    border-left: 1px solid #555;
    display: inline-block;
    float: left;
    margin: 0;
}
nav a {
    background: #222;
    color: #fff;
    display: block;
    font-family: Helvetica,Arial,Verdana,sans-serif;
    font-size: 12px;
    padding: 10px 15px;
    text-decoration: none;
}
nav ul li ul li:hover {
    background: #444 none repeat scroll 0 0;
}
nav a:hover {
    background-color: #000000;
}
nav ul ul {
    display: none;
    position: absolute;
    top: 35px;
}
nav ul li:hover > ul {
    display: inherit;
}
nav ul ul li {
    display: list-item;
    float: none;
    position: relative;
    width: 170px;
}
nav ul ul ul li {
    left: 170px;
    position: relative;
    top: -60px;
}
nav ul li > a::after {
    content: " ";
    display: inline;
    font-family: fontawesome;
}
nav ul li > a:only-child::after {
    content: "";
}
@media all and (max-width: 768px) {
nav {
    margin: 0;
}
.toggle + a, .menu {
    display: none;
}
.toggle {
    background: #333;
    border: medium none;
    color: #ffffff;
    display: block;
    font-family: Helvetica,Arial,Verdana,sans-serif;
    font-size: 12px;
    padding: 10px 15px;
    text-decoration: none;
}
.toggle:hover {
    background-color: #000000;
}
[id^="drop"]:checked + ul {
    display: block;
}
nav ul li {
    display: block;
    width: 100%;
}
nav ul ul .toggle, nav ul ul a {
    padding: 0 40px;
}
nav ul ul ul a {
    padding: 0 80px;
}
nav a:hover, nav ul ul ul a {
    background-color: #000000;
}
nav ul li ul li .toggle, nav ul ul a, nav ul ul ul a {
    color: #ffffff;
    font-size: 12px;
    padding: 10px 15px;
}
nav ul li ul li .toggle, nav ul ul a {
    background-color: #212121;
}
nav ul ul {
    color: #ffffff;
    float: none;
    position: static;
}
nav ul ul li:hover > ul, nav ul li:hover > ul {
    display: none;
}
nav ul ul li {
    display: block;
    width: 100%;
}
nav ul ul ul li {
    position: static;
}
}
@media all and (max-width: 330px) {
nav ul li {
    display: block;
    width: 94%;
}
}
@media only screen and (min-width: 769px) {
nav ul {
    margin-left: 8%;
}
nav ul ul {
    margin-left: 0;
}
}

html {
background: #202020; margin: 0; padding:0;
}

body {
	background: #202020;
	color: #CECECE;
	text-align: center;
	line-height: 1.4;
	margin: 0;
	font-family: Tahoma, Verdana, Arial, Sans-Serif;
	font-size: 13px;
	overflow-y: scroll;
}

a:link, a:visited {
	color: #93A774;
	text-decoration: none;
}

a:hover,a:active {
	color: #ccc;
	text-decoration: none;
}

#container {
	text-align: left;
	line-height: 1.4;
	margin: 0;
	min-width: 990px;
	
	color: #CECECE;
	font-family: Tahoma, Verdana, Arial, Sans-Serif;
	font-size: 13px;
}

.wrapper {
	width: 85%;
	min-width: 970px;
	max-width: 1500px;
	margin: auto auto;
}

#logo {
	background: #202020;
	padding: 10px 0;
	border-bottom: 1px solid #252525;
}

#content {
	background: #202020;
	width: auto !important;
	padding: 20px 10px;
	overflow: hidden;
}

#header ul.menu li a i {
   color:#CECECE;
}

#header ul.menu {
	margin: 0;
	padding: 0;
	list-style: none;
}

#header ul.menu li {
	margin: 0 7px;
	display: inline;
}

#logo ul.top_links {
	font-weight: bold;
	text-align: right;
	margin: -10px 5px 0 0;
}

#panel .upper a.logout {
	font-weight: bold;
	padding-right: 20px;
	margin-left: 10px;
}

#panel .upper a.login,
#panel .upper a.lost_password {
	padding-left: 20px;
	margin-left: 10px;
	font-weight: bold;
}

#panel .upper a.register {
	padding-right: 20px;
	margin-left: 10px;
	font-weight: bold;
}

#panel .lower ul.panel_links {
	float: left;
}

#panel .lower ul.user_links {
	float: right;
}

#panel .lower ul.user_links li a {
	padding: 0;
	background-image: none;
}

#panel .upper {
	background: #768D60;
	color: #fff;
	padding: 7px;
	clear: both;
}

#panel .upper a:link,
#panel .upper a:visited{
	color:#FFF;
}

#panel .upper a:hover,
#panel .upper a:active {
	color: #ccc;
}

#panel .lower {
	background: #353535;
	padding: 5px;
}

#panel .lower a:link,
#panel .lower a:visited {
	color:#ccc;
}

#panel .lower a:hover,
#panel .lower a:active {
	color: #fff;
}

#search {
	border: 0;
	padding: 0;
	margin: 0;
	float: right;
	vertical-align: middle;
}

#search input.textbox {
	border-color: #353535;
}

#search input.button {
	background: #444444;
	color: #fff;
}

#search input {
	margin: -3px 0;
}

#quick_login .remember_me input {
	vertical-align: middle;
	margin: -3px 0 0 5px;
}

#footer {
	clear: both;
}

#footer ul.menu {
	margin: 0;
	padding: 0;
	list-style: none;
}

#footer ul.menu li {
	margin: 0 5px;
	display: inline;
}

#footer .upper {
	background: #353535;
	padding: 6px;
	font-size: 12px;
	overflow: hidden;
}

#footer a:link,
#footer a:visited,
#footer a:hover,
#footer a:active {
	color: #CCC;
}

#footer .upper .language {
	float: right;
	margin: -1px;
	margin-left: 15px;
}

#footer .upper .language select {
	border-color: #ccc;
}

#footer .upper .theme {
	float: right;
	margin: -1px;
	margin-left: 15px;
}

#footer .upper .theme select {
	border-color: #353535;
}

#footer .upper ul.bottom_links {
	float: left;
	margin: 4px 0 0 0;
}

#footer .lower {
	color: #CECECE;
	background: #262626;
	padding: 6px 6px 12px 6px;
	overflow: hidden;
	font-size: 11px;
}

#footer .lower a:link,
#footer .lower a:visited {
	color: #ccc;
	font-weight: bold;
}

#footer .lower a:hover,
#footer .lower a:active {
	color: #fff;
	text-decoration: none;
	font-weight: bold;
}

#footer .lower #current_time {
	float: right;
	color: #888;
}

#debug {
	float: right;
	text-align: right;
	margin-top: 20px;
	font-size: 11px;
}

.scaleimages img {
	max-width: 100%;
}

.forum_status {
height: 25px;width: 25px;font-size: 25px;text-align: center;
}

.forum_status i {
display: inline-block;line-height: 25px;
}

.forum_on {
color: #99B67D;
}

.forum_off, .forum_offlock, .forum_offlink {
color: #666;
}

