#shoutbox {
	margin-bottom: 10px;
	border: solid 2px rgba(0,0,0,0.1);
}

#shoutbox .head {
	background: #3F5B1D;
	color: #FFFFFF;
	padding: 8px;
	border-top-left-radius: 6px;
 	border-top-right-radius: 6px;
}

#shoutbox.front .head {
 cursor: pointer;
}

#shoutbox .head .right {
	color: #fff;
	float: right;
	margin: 0;
	font-size: 13px;
}

#shoutbox > .head > .right > a {
 
	color: white;
}

#shoutbox.collapsed .head {
 opacity: 0.6;
}

#shoutbox.collapsed .body {
 display: none;
}

#shoutbox .panel {
 border-top: solid 2px rgba(0,0,0,0.1);
}

#shoutbox input.text {
	background: #FFFFFF;
	width: 100%;
	color: #202020;
	margin: 0;
	padding: 10px 8px;
	box-sizing: border-box;
	border: none;
	box-shadow: inset 0 2px 4px rgba(0,0,0,0.08);
	
	font-family: Arial, sans-serif;
	font-size: 13px;
}

#shoutbox .minposts, #shoutbox .blocked {
 padding: 6px; font-size: 11px;
}

#shoutbox .panel.minposts {
 background: #FFFED8; color: #727250;
}

#shoutbox .panel.blocked {
	background: #11111111;
	color: #5C7841;
}

#shoutbox .panel p {
 margin: 0;
}

#shoutbox .window {
 border-top: solid 2px rgba(0,0,0,0.1); overflow-y: scroll;
}

#shoutbox .data {
 display: table; width: 100%; border-top: solid 2px rgba(0,0,0,0.1); font-family: Arial, sans-serif; font-size: 13px;
}

#shoutbox.front .data {
 border-top: none;
}

#shoutbox .entry {
 display: table-row !important; width: 100%; transition: background-color 0.2s;
}

#shoutbox .entry:nth-child(even) {
 background-color: rgba(0,0,0,0.01);
}

#shoutbox .entry.new {
 background-color: rgba(21, 90, 12, 0.15);
}

#shoutbox .entry:target {
 background-color: rgba(50,200,255,0.1);
}

#shoutbox .entry > div {
 border-bottom: dashed 1px rgba(0,0,0,0.05);
}

#shoutbox .entry:last-child > div {
 border-bottom: none;
}

#shoutbox .entry > div {
 display: table-cell; padding: 6px;
}

#shoutbox .avatar img {
 margin: 0 auto; vertical-align: middle; max-height: 20px; max-width: 20px; border: solid 1px rgba(255,255,255,0.1); border-radius: 25%; box-shadow: 0 0 2px rgba(0,0,0,0.1); cursor: pointer;
}

#shoutbox .user {
 border-right: solid 1px rgba(0,0,0,0.05); text-align: right; white-space: nowrap;
}

#shoutbox .text {
	width: 100%;
	color: #CECECE; 
	word-break: normal;
	word-wrap: normal;
}

#shoutbox .info {
 font-size: 11px; color: #AAA; white-space: nowrap; text-align: right;
}

#shoutbox .entry.unread .info:before {
 display: inline-block; position: relative; top: -2px; margin-right: 10px; height: 4px; width: 4px; content: ''; background: rgba(255,100,0,0.8); border-radius: 10px;
}

#shoutbox .info a {
 color: inherit;
}

#shoutbox .mod {
 padding: 6px 8px; font-size: 9px; font-weight: bold; color: #AAA; text-decoration: none;
}

#shoutbox .mod:nth-of-type(2) {
 margin-right: 5px; border-left: solid 1px rgba(0,0,0,0.1);
}

#shoutbox  .ip {
 margin-right: 10px; color: #a0a0a0;
}

.dnt_announcements_admins {
	color: #00529B;
	background-color: #BDE5F8;
	padding: 10px;
	border-left: 3px solid #00529B;
	border-radius: 2px;
	margin: 0px;
	text-align: center;
	margin-bottom: 10px;
}

.dnt_announcements_registered {
	color: #279025;
    background-color: #DFF2BF;
	padding: 10px;
	border-left: 3px solid #279025;
	border-radius: 2px;
	margin: 5px 0px 10px 0px;
	text-align: center;
}

.dnt_announcements_mods {
    color: #9F6000;
    background-color: #FEEFB3;
	padding: 10px;
	border-left: 3px solid #9F6000;
	border-radius: 2px;
	margin: 0px;
	text-align: center;
	margin-bottom: 10px;
}

.dnt_announcements_guests {
    color: #D8000C;
    background-color: #CECECE;
	padding: 10px;
	border: 3px solid #D8000C;
	border-radius: 5px;
	margin: 0px;
	text-align: center;	
	font-weight: bold;
	font-size: 17px;
	margin-bottom: 10px
}

.dnt_announcements_admins > span, .dnt_announcements_registered > span, .dnt_announcements_mods > span, .dnt_announcements_guests > span{
