.star_rating,
.star_rating li a:hover,
.star_rating .current_rating {
	background: url(images/star_rating.png) left -1000px repeat-x;
	vertical-align: middle;
}

.star_rating {
	position: relative;
	width:80px;
	height:16px;
	overflow: hidden;
	list-style: none;
	margin: 0;
	padding: 0;
	background-position: left top;
}

td .star_rating {
	margin: auto;
}

.star_rating li {
	display: inline;
}

.star_rating li a,
.star_rating .current_rating {
	position: absolute;
	text-indent: -1000px;
	height: 16px;
	line-height: 16px;
	outline: none;
	overflow: hidden;
	border: none;
	top:0;
	left:0;
}

.star_rating_notrated li a:hover {
	background-position: left bottom;
}

.star_rating li a.one_star {
	width:20%;
	z-index:6;
}

.star_rating li a.two_stars {
	width:40%;
	z-index:5;
}

.star_rating li a.three_stars {
	width:60%;
	z-index:4;
}

.star_rating li a.four_stars {
	width:80%;
	z-index:3;
}

.star_rating li a.five_stars {
	width:100%;
	z-index:2;
}

.star_rating .current_rating {
	z-index:1;
	background-position: left center;
}

.star_rating_success,
.success_message {
	color: #00b200;
	font-weight: bold;
	font-size: 10px;
	margin-bottom: 10px;
}

.inline_rating {
	background: url(images/star_rating.png) left -1000px repeat-x;
	float: left;
	vertical-align: middle;
	padding-right: 5px;
}

ul.thread_tools,ul.thread_tools li{
	list-style: none;
	padding: 0;
	margin: 0;
}

ul.thread_tools li {
	padding-left: 0;
	padding-bottom: 4px;
	margin-bottom: 3px; 
	font-size: 11px;
}

ul.thread_tools li.printable:before {
    font-family: FontAwesome;
    font-size: 10px;
    position: absolute; 
    z-index: 1;
    margin-left: -20px;
}

ul.thread_tools li.printable:after{
    font-family: FontAwesome;
    font-size: 14px;
    color: #696969;
    content: "\f02f";
	float: left;
	position: relative; 
    z-index: 0; 
	padding-right: 5px;
}

ul.thread_tools li.sendthread:before {
    font-family: FontAwesome;
    font-size: 8px;
    position: absolute; 
    z-index: 1;
    margin-left: -20px;
}

ul.thread_tools li.sendthread:after {
